import json

def apply_horizontal_gap_rule(grid):
    """Fill background cells between foreground cells in each row"""
    result = [row[:] for row in grid]
    bg_val = 9
    fg_val = 8
    fill_val = 2

    for r in range(len(grid)):
        # Find all foreground positions
        fg_positions = [c for c in range(len(grid[r])) if grid[r][c] == fg_val]

        # For each gap between consecutive fg cells, fill with fill_val
        for i in range(1, len(fg_positions)):
            gap_start = fg_positions[i-1] + 1
            gap_end = fg_positions[i]
            for c in range(gap_start, gap_end):
                if result[r][c] == bg_val:
                    result[r][c] = fill_val

    return result

def transform(grid):
    return apply_horizontal_gap_rule(grid)
